//! The filesystem hosted effects, marshalled onto the session.
//!
//! Every function here has the same three-part shape: take the owned path
//! argument(s) as a `String` (which releases them — [`native_into_string`]),
//! call the session effect through [`effect`], and marshal the result into the
//! generated `Try` type. The `*_ok`/`*_err` constructors that build those types
//! are uniform — an `Ok`/`Err` tag over a value or an `IOErr` — so they are
//! generated by the macros below rather than written twenty times.

use core::mem::ManuallyDrop;

use crate::marshal::{
    effect, host, io_err, native_from_str, native_into_string, roc_bytes_from_slice,
    roc_bytes_into_vec, rocstr_into_string,
};
use crate::roc_platform_abi::{
    DirOrFileOrOtherOrSymLink, HostDirCreateResult, HostDirCreateResultPayload,
    HostDirCreateResultTag, HostDirListResult, HostDirListResultPayload, HostDirListResultTag,
    HostFileDeleteResult, HostFileDeleteResultPayload, HostFileDeleteResultTag,
    HostFileIsExecutableResult, HostFileIsExecutableResultPayload, HostFileIsExecutableResultTag,
    HostFileReadBytesResult, HostFileReadBytesResultPayload, HostFileReadBytesResultTag,
    HostFileReadUtf8Result, HostFileReadUtf8ResultPayload, HostFileReadUtf8ResultTag,
    HostFileSizeInBytesResult, HostFileSizeInBytesResultPayload, HostFileSizeInBytesResultTag,
    HostFileTimeAccessedResult, HostFileTimeAccessedResultPayload, HostFileTimeAccessedResultTag,
    HostPathCanonicalizeResult, HostPathCanonicalizeResultPayload, HostPathCanonicalizeResultTag,
    HostPathTypeResult, HostPathTypeResultPayload, HostPathTypeResultTag, IOErr, RocList,
    RocListWith, RocStr, UnixBytesOrUtf8OrWindowsU16s as Native,
};
use brush_platform::{PathKind, PlatformEffects};

// A result type whose `Ok` carries a value and whose `Err` carries an `IOErr`.
// Generates `<lc>_ok(value) -> Ty` and `<lc>_err(IOErr) -> Ty`.
macro_rules! io_value_result {
    ($ok_fn:ident, $err_fn:ident, $ty:ident, $tag:ident, $payload:ident, $ok_ty:ty) => {
        fn $ok_fn(value: $ok_ty) -> $ty {
            $ty {
                payload: $payload {
                    ok: ManuallyDrop::new(value),
                },
                tag: $tag::Ok,
            }
        }
        fn $err_fn(error: IOErr) -> $ty {
            $ty {
                payload: $payload {
                    err: ManuallyDrop::new(error),
                },
                tag: $tag::Err,
            }
        }
    };
}

// A result type whose `Ok` is unit and whose `Err` carries an `IOErr`.
macro_rules! io_unit_result {
    ($ok_fn:ident, $err_fn:ident, $ty:ident, $tag:ident, $payload:ident) => {
        fn $ok_fn() -> $ty {
            $ty {
                payload: $payload { ok: [] },
                tag: $tag::Ok,
            }
        }
        fn $err_fn(error: IOErr) -> $ty {
            $ty {
                payload: $payload {
                    err: ManuallyDrop::new(error),
                },
                tag: $tag::Err,
            }
        }
    };
}

io_unit_result!(
    dir_ok,
    dir_err,
    HostDirCreateResult,
    HostDirCreateResultTag,
    HostDirCreateResultPayload
);
io_unit_result!(
    file_ok,
    file_err,
    HostFileDeleteResult,
    HostFileDeleteResultTag,
    HostFileDeleteResultPayload
);
io_value_result!(
    dir_list_ok,
    dir_list_err,
    HostDirListResult,
    HostDirListResultTag,
    HostDirListResultPayload,
    RocList<Native>
);
io_value_result!(
    read_bytes_ok,
    read_bytes_err,
    HostFileReadBytesResult,
    HostFileReadBytesResultTag,
    HostFileReadBytesResultPayload,
    RocListWith<u8, false>
);
io_value_result!(
    read_utf8_ok,
    read_utf8_err,
    HostFileReadUtf8Result,
    HostFileReadUtf8ResultTag,
    HostFileReadUtf8ResultPayload,
    RocStr
);
io_value_result!(
    bool_ok,
    bool_err,
    HostFileIsExecutableResult,
    HostFileIsExecutableResultTag,
    HostFileIsExecutableResultPayload,
    bool
);
io_value_result!(
    size_ok,
    size_err,
    HostFileSizeInBytesResult,
    HostFileSizeInBytesResultTag,
    HostFileSizeInBytesResultPayload,
    u64
);
io_value_result!(
    time_ok,
    time_err,
    HostFileTimeAccessedResult,
    HostFileTimeAccessedResultTag,
    HostFileTimeAccessedResultPayload,
    u128
);
io_value_result!(
    path_type_ok,
    path_type_err,
    HostPathTypeResult,
    HostPathTypeResultTag,
    HostPathTypeResultPayload,
    DirOrFileOrOtherOrSymLink
);

// `path_canonicalize`'s error is unit — the caller reports its own message — so
// it does not fit the `IOErr` macros.
fn canonicalize_ok(value: Native) -> HostPathCanonicalizeResult {
    HostPathCanonicalizeResult {
        payload: HostPathCanonicalizeResultPayload {
            ok: ManuallyDrop::new(value),
        },
        tag: HostPathCanonicalizeResultTag::Ok,
    }
}
fn canonicalize_err() -> HostPathCanonicalizeResult {
    HostPathCanonicalizeResult {
        payload: HostPathCanonicalizeResultPayload { err: [] },
        tag: HostPathCanonicalizeResultTag::Err,
    }
}

/// Resolves one owned path argument, short-circuiting to `$err` on an
/// unnameable path (D45) with the argument already released.
macro_rules! path_arg {
    ($arg:expr, $host:expr, $err:ident) => {
        match native_into_string($arg, $host) {
            Ok(path) => path,
            Err(error) => return $err(io_err(&error, $host)),
        }
    };
}

// --- Directories -----------------------------------------------------------

#[unsafe(no_mangle)]
pub extern "C" fn hosted_dir_create(path: Native) -> HostDirCreateResult {
    let host = host();
    let path = path_arg!(path, &host, dir_err);
    match effect(|s| s.dir_create(&path)) {
        Ok(()) => dir_ok(),
        Err(error) => dir_err(io_err(&error, &host)),
    }
}

