#[unsafe(no_mangle)]
pub extern "C" fn hosted_dir_list(path: Native) -> HostDirListResult {
    let host = host();
    let path = path_arg!(path, &host, dir_list_err);
    match effect(|s| s.dir_list(&path)) {
        Ok(entries) => {
            let list = unsafe { RocList::<Native>::allocate(entries.len(), &host) };
            for (index, entry) in entries.iter().enumerate() {
                unsafe {
                    list.elements
                        .add(index)
                        .write(native_from_str(entry, &host));
                }
            }
            dir_list_ok(list)
        }
        Err(error) => dir_list_err(io_err(&error, &host)),
    }
}

