// The three time effects are deferred (D46): the session returns `Unsupported`,
// which marshals to the `Unsupported` `IOErr`. The path is still resolved and
// released first, so an unnameable path is `NotFound` as everywhere else.
#[unsafe(no_mangle)]
pub extern "C" fn hosted_file_time_accessed(path: Native) -> HostFileTimeAccessedResult {
    let host = host();
    let path = path_arg!(path, &host, time_err);
    match effect(|s| s.file_time_accessed(&path)) {
        Ok(value) => time_ok(value),
        Err(error) => time_err(io_err(&error, &host)),
    }
}

