// --- Paths -----------------------------------------------------------------

#[unsafe(no_mangle)]
pub extern "C" fn hosted_path_type(path: Native) -> HostPathTypeResult {
    let host = host();
    let path = path_arg!(path, &host, path_type_err);
    match effect(|s| s.path_type(&path)) {
        Ok(kind) => path_type_ok(match kind {
            PathKind::Dir => DirOrFileOrOtherOrSymLink::Dir,
            PathKind::File => DirOrFileOrOtherOrSymLink::File,
            PathKind::SymLink => DirOrFileOrOtherOrSymLink::SymLink,
            PathKind::Other => DirOrFileOrOtherOrSymLink::Other,
        }),
        Err(error) => path_type_err(io_err(&error, &host)),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn hosted_path_canonicalize(path: Native) -> HostPathCanonicalizeResult {
    let host = host();
    // The error is unit here, so an unnameable path is simply the `Err` — the
    // caller renders its own message, as `basic-cli` documents.
    let path = match native_into_string(path, &host) {
        Ok(path) => path,
        Err(_) => return canonicalize_err(),
    };
    match effect(|s| s.path_canonicalize(&path)) {
        Ok(resolved) => canonicalize_ok(native_from_str(&resolved, &host)),
        Err(_) => canonicalize_err(),
    }
}
